#!/usr/bin/env python3
"""Generate the `hrms-mock` profile document inside backend/src/main/resources/application.yaml from HrmsApi.

One setting per API holds its path and direction (owner 2026-11-05: "1 API = 1 parameter"); this profile
points every API at ONE base address and sets the direction OUTBOUND (Payroll calls HRMS). It lives in
application.yaml as a profile-activated document (no separate file), between the markers

    # >>> hrms-mock (generated by scripts/integration/gen_hrms_profile.py, do not edit by hand)
    # <<< hrms-mock

and StartupGuards refuse the profile in production and in a UAT that is not a demo stack. The base address,
the api-key and the login come from the environment, so the same document serves local, dev and demo.
Paths are those of FCI's Postman collection (the enum's collection path).

Usage: python scripts/integration/gen_hrms_profile.py
"""
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
ENUM = ROOT / "backend/src/main/java/in/gov/fci/payroll/integration/api/HrmsApi.java"
YAML = ROOT / "backend/src/main/resources/application.yaml"
BEGIN = "# >>> hrms-mock (generated by scripts/integration/gen_hrms_profile.py, do not edit by hand)"
END = "# <<< hrms-mock"

HEADER = """---
# Profile hrms-mock: Payroll CALLS the HRMS APIs (direction OUTBOUND) at one base address - here the FCI HRMS
# mock server (default http://localhost:8080). Allowed only on local, dev and demo runs: StartupGuards refuse it
# with prod and with a uat that is not a demo stack. One setting per API holds its path. The base address and the
# secrets come from the ENVIRONMENT (12-factor); set per environment: FCI_HRMS_BASE_URL, FCI_HRMS_API_KEY (or
# _FILE), FCI_HRMS_USERNAME, FCI_HRMS_PASSWORD (or _FILE). Nothing secret is in this file. One API's path is
# overridden with FCI_INTEGRATION_HRMS_API_<CODE>_PATH, its direction with ..._DIRECTION (INBOUND = Payroll
# publishes it, OUTBOUND = Payroll calls it); its call policy under api.<code>.call.* (see HrmsApiProperties).
spring:
  config:
    activate:
      on-profile: hrms-mock
fci:
  integration:
    hrms:
      base-url: ${FCI_HRMS_BASE_URL:http://localhost:8080}
      client:
        api-key: ${FCI_HRMS_API_KEY:}
        api-key-file: ${FCI_HRMS_API_KEY_FILE:}
        credentials:
          username: ${FCI_HRMS_USERNAME:}
          password: ${FCI_HRMS_PASSWORD:}
          password-file: ${FCI_HRMS_PASSWORD_FILE:}
          token-skew-seconds: 60
      # Call policy for every API below (flags Y/N, times in ms); one API overrides any of it under
      # api.<code>.call.* (timeouts, mask-data, log-request, log-response, pool.*).
      defaults:
        connect-timeout-ms: 10000
        read-timeout-ms: 60000
        timeout-ms: 30000
        mask-data: Y
        log-request: Y
        log-response: Y
      # The Administrator's API console of X-03 (HrmsConsoleService) may call every OUTBOUND API below.
      console:
        enabled: true
      # Concurrent calls and the wait for a free slot, per API (R-INT); the connection test has its own.
      bulkhead:
        connection_test: {max-concurrent-calls: 2, max-wait-millis: 500}"""


def block(rows) -> str:
    out = [BEGIN, HEADER]
    out += [f"        {code}: {{max-concurrent-calls: 5, max-wait-millis: 1000}}" for code, _, _ in rows]
    out.append("      api:")
    out += [f"        {code}: {{path: {path}, direction: OUTBOUND}}" for code, _, path in rows]
    out.append(END)
    return "\n".join(out) + "\n"


def main() -> None:
    text = ENUM.read_text(encoding="utf8")
    # The enum constants are wrapped over several lines by the formatter: match across newlines.
    rows = re.findall(
        r'\b[A-Z][A-Z_0-9]*\(\s*"([a-z0-9_]+)",\s*Selection\.\w+,\s*"(\w+)",\s*"([^"]+)"\s*\)', text
    )
    if not rows:
        raise SystemExit("no API found in HrmsApi.java")
    doc = YAML.read_text(encoding="utf8").replace("\r\n", "\n")
    new = block(rows)
    if BEGIN in doc and END in doc:
        head, rest = doc.split(BEGIN, 1)
        tail = rest.split(END, 1)[1].lstrip("\n")
        doc = head + new + tail
    else:
        doc = doc.rstrip("\n") + "\n" + new
    YAML.write_text(doc, encoding="utf8", newline="\n")
    print(f"{len(rows)} APIs -> hrms-mock document in {YAML}")


if __name__ == "__main__":
    main()
